import type { Metadata } from 'next';
import { siteName } from '@/content/site';

/**
 * The shared social preview, generated by app/opengraph-image.tsx. A page that sets its own
 * `openGraph` replaces the inherited one, so the image has to be listed again.
 */
const socialImage = { url: '/opengraph-image', width: 1200, height: 630, alt: 'Bluechip Branding & Design: branding, websites, and signage' };

/** Per-page metadata with matching canonical URL and social previews. */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, siteName, type: 'website', images: [socialImage] },
    twitter: { card: 'summary_large_image', title, description, images: [socialImage] },
  };
}
